preConditionHook:
// Breakout clears by half a bar (Brian's phone notes P7, p. 18): the highest
// high of bars 1..X below this bar's midpoint (short: the lowest low above it). Not
// BreakoutClearsPriorExtremeByMargin (fixed tick margin, not half the bar).
// Window extremes as the Extremes loop: seeded at bar 1, strict scan.
priorHi = high[1];
priorLo = low[1];
for (ii = 2; ii <= (int)X; ++ii) {
    if (el_gt(high[ii], priorHi)) priorHi = high[ii];
    if (el_lt(low[ii], priorLo)) priorLo = low[ii];
}
